import {rpc as request} from './request.js';
import {renderFirmware, shareCurrentFirmware} from './updates.js';
import {uploadFirmware} from './upload.js';
import {liveView} from './live.js';
import {deviceOverview} from './devices.js';
const $ = id => document.getElementById(id);
let pixels;
let callbacks, currentStatus, busy = false, timer, debounce;
let serial = Promise.resolve();
const pending = new Map();
const rpc = command => request(location.origin, command);
const message = text => { $('managementMessage').textContent = text; $('feedback').textContent = text; };
// Keep polling, uploads and lighting commands serialized against the device's bounded RPC queue.
function action(operation) {
	serial = serial.then(async () => {
		busy = true;
		try { await operation(); } catch (error) { message(error.message); }
		finally { busy = false; if (pending.size) debounce = setTimeout(drain,250); }
	});
	return serial;
}
// Read reported state, never browser-stored device settings, during normal page hydration.
async function refresh() {
	const status = await rpc({op:'status'});
	if (!Array.isArray(status.devices)) throw new Error('Invalid device status');
	currentStatus = status;
	if (!pending.size) callbacks.receiveDevices({...status, devices:deviceOverview(status).physicalDevices});
	callbacks.setEnabled(Boolean(status.master && status.settled));
	$('leader').textContent = 'Master: ' + status.masterIp;
	$('openMaster').hidden = status.master || !/^\d{1,3}(\.\d{1,3}){3}$/.test(status.masterIp || '');
	$('openMaster').onclick = () => { if (/^\d{1,3}(\.\d{1,3}){3}$/.test(status.masterIp || '')) location.href = 'http://' + status.masterIp + '/'; };
	if ($('managementDialog').open) renderFirmware(status,$);
	return status;
}
// Transmit only changed properties; byte-sized effect parameters stay compatible with WLED.
function change(target, state, keys) {
	if (!target || !currentStatus?.master || !currentStatus.settled) { message('Open the elected master to control lighting.'); return; }
	const key = 'lighting:' + target;
	const patch = pending.get(key)?.body || {independent:true};
	const segment = patch.seg?.[0] || {id:0};
	for (const key of keys) {
		if (key === 'on') patch.on = state.on;
		if (key === 'brightness') patch.bri = Math.round(state.brightness * 255 / 100);
		if (key === 'color') segment.col = [state.color.match(/[0-9a-f]{2}/gi).map(part => parseInt(part,16))];
		if (key === 'effect') segment.fx = [0,2,9][state.effect];
		if (key === 'speed') segment.sx = state.speed;
		if (key === 'intensity') segment.ix = state.intensity;
	}
	if (Object.keys(segment).length > 1) patch.seg = [segment];
	pending.delete(key); pending.set(key,{op:'lighting',target,body:patch});
	clearTimeout(debounce); debounce = setTimeout(drain,250);
}
// Coalesce temporary physical-output calibration without changing synchronization or presets.
function calibrate(target, whiteReduction) {
	if (!target || !currentStatus?.master || !currentStatus.settled) return;
	const key = 'calibration:' + target;
	pending.delete(key); pending.set(key,{op:'calibration',target,body:{whiteReduction}});
	clearTimeout(debounce); debounce = setTimeout(drain,250);
}
// Debounce sliders and bound each target to its latest pending patch, without retrying failed writes blindly.
async function drain() {
	if (busy || !pending.size) return;
	await action(async () => {
		const [key,command] = pending.entries().next().value; pending.delete(key);
		await rpc(command);
		if (!pending.size) await refresh();
		$('feedback').textContent = '';
	});
}
// Refresh controls separately from the read-only LED output feed.
function schedule() {
	clearTimeout(timer);
	timer = setTimeout(async () => {
		if (!document.hidden && !busy && !pending.size) await action(refresh);
		schedule();
	}, $('managementDialog').open ? 3000 : 30000);
}
window.glassDeviceBridge = {change, calibrate, selectLiveDevice(device) { pixels?.select(device,currentStatus?.localId); }, setLiveVisible(visible) { pixels?.setVisible(visible); }, start(api) {
	pixels = liveView(api.receivePixels);
	callbacks = api; callbacks.setEnabled(false);
	$('openManagement').onclick = () => { $('managementDialog').showModal(); action(refresh); schedule(); };
	$('closeManagement').onclick = () => { $('managementDialog').close(); schedule(); };
	$('saveWifi').onclick = () => action(async () => {
		await rpc({op:'wifi',confirm:true,body:{ssid:$('ssid').value,password:$('wifiPassword').value}});
		$('wifiPassword').value = ''; message('Wi-Fi saved. Reboot to connect.');
	});
	$('reboot').onclick = () => action(async () => { await rpc({op:'reboot'}); message('Reboot requested.'); });
	$('applySettings').onclick = () => action(async () => {
		const body = {sync:$('sync').checked,bootOn:$('bootOn').checked,bootBrightness:Number($('bootBrightness').value),transitionMs:Number($('transition').value)};
		if ($('name').value) body.name = $('name').value;
		await rpc({op:'settings',target:$('target').value,body}); message('Settings applied or queued.');
	});
	$('upload').onclick = () => action(async () => {
		await uploadFirmware(rpc,$('firmware').files[0],(received,total) => { $('progress').hidden=false; $('progress').value=100*received/total; });
		await refresh(); message('Firmware staged and verified.');
	});
	$('shareCurrent').onclick = () => action(async () => { const result=await shareCurrentFirmware(rpc,refresh,$('firmwareTarget').value); message('Update queued for '+result.queued+' device(s).'); });
	$('rollout').onclick = () => action(async () => { const result=await rpc({op:'rollout',target:$('firmwareTarget').value}); await refresh(); message('Update queued for '+result.queued+' device(s).'); });
	$('installLocal').onclick = () => action(async () => { if (confirm('Install staged firmware on this device?')) { await rpc({op:'installLocal'}); message('Installation started.'); } });
	document.addEventListener('visibilitychange',schedule);
	action(refresh).then(schedule);
}};
